on 3.5 to 6.3).";}}s:7:"actions";a:2:{i:0;O:8:"stdClass":6:{s:4:"name";s:10:"learn-more";s:7:"locales";a:1:{i:0;O:8:"stdClass":2:{s:6:"locale";s:5:"en_US";s:5:"label";s:10:"Learn more";}}s:3:"url";s:88:"https://developer.woocommerce.com/2022/03/10/woocommerce-3-5-10-6-3-1-security-releases/";s:18:"url_is_admin_query";b:0;s:10:"is_primary";b:1;s:6:"status";s:10:"unactioned";}i:1;O:8:"stdClass":6:{s:4:"name";s:7:"dismiss";s:7:"locales";a:1:{i:0;O:8:"stdClass":2:{s:6:"locale";s:5:"en_US";s:5:"label";s:7:"Dismiss";}}s:3:"url";s:0:"";s:18:"url_is_admin_query";b:0;s:10:"is_primary";b:0;s:6:"status";s:8:"actioned";}}s:5:"rules";a:3:{i:0;O:8:"stdClass":2:{s:4:"type";s:18:"publish_after_time";s:13:"publish_after";s:19:"2022-03-10 18:45:04";}i:1;O:8:"stdClass":2:{s:4:"type";s:2:"or";s:8:"operands";a:28:{i:0;O:8:"stdClass":4:{s:4:"type";s:14:"plugin_version";s:6:"plugin";s:11:"woocommerce";s:8:"operator";s:1:"=";s:7:"version";s:6:"3.5.10";}i:1;O:8:"stdClass":4:{s:4:"type";s:14:"plugin_version";s:6:"plugin";s:11:"woocommerce";s:8:"operator";s:1:"=";s:7:"version";s:5:"3.6.7";}i:2;O:8:"stdClass":4:{s:4:"type";s:14:"plugin_version";s:6:"plugin";s:11:"woocommerce";s:8:"operator";s:1:"=";s:7:"version";s:5:"3.7.3";}i:3;O:8:"stdClass":4:{s:4:"type";s:14:"plugin_version";s:6:"plugin";s:11:"woocommerce";s:8:"operator";s:1:"=";s:7:"version";s:5:"3.8.3";}i:4;O:8:"stdClass":4:{s:4:"type";s:14:"plugin_version";s:6:"plugin";s:11:"woocommerce";s:8:"operator";s:1:"=";s:7:"version";s:5:"3.9.5";}i:5;O:8:"stdClass":4:{s:4:"type";s:14:"plugin_version";s:6:"plugin";s:11:"woocommerce";s:8:"operator";s:1:"=";s:7:"version";s:5:"4.0.4";}i:6;O:8:"stdClass":4:{s:4:"type";s:14:"plugin_version";s:6:"plugin";s:11:"woocommerce";s:8:"operator";s:1:"=";s:7:"version";s:5:"4.1.4";}i:7;O:8:"stdClass":4:{s:4:"type";s:14:"plugin_version";s:6:"plugin";s:11:"woocommerce";s:8:"operator";s:1:"=";s:7:"version";s:5:"4.2.5";}i:8;O:8:"stdClass":4:{s:4:"type";s:14:"plugin_version";s:6:"plugin";s:11:"woocommerce";s:8:"operat