INSERT INTO `wp_posts` VALUES (587,1,'2015-11-05 09:52:56','2015-11-05 09:52:56','<div class="row stm-forms-sm">\n    <div class="col-md-4 col-sm-4">\n       <div class="form-group">\n         <div class="form-label-small">Name</div>\n         [text* your-name]\n       </div>\n    </div>\n    <div class="col-md-4 col-sm-4">\n       <div class="form-group">\n         <div class="form-label-small">Email</div>\n         [email* your-email]\n       </div>\n    </div>\n    <div class="col-md-4 col-sm-4">\n       <div class="form-group">\n         <div class="form-label-small">Phone</div>\n         [tel* your-tel]\n       </div>\n    </div>\n</div>\n<div class="row stm-forms-sm">\n    <div class="col-md-4 col-sm-4">\n       <div class="form-group">\n         <div class="form-label-small">Make/Model</div>\n         [text* make-model]\n       </div>\n    </div>\n    <div class="col-md-4 col-sm-4">\n       <div class="form-group">\n         <div class="form-label-small">Mileage (optional)</div>\n         [text mileage]\n       </div>\n    </div>\n    <div class="col-md-4 col-sm-4">\n       <div class="form-group">\n         <div class="form-label-small">Best time</div>\n         <div class="stm-datepicker-input-icon">\n	    [text* time class:stm-date-timepicker]\n	 </div>\n       </div>\n    </div>\n</div>\n<hr class="form-hr"/>\n<div class="row">\n    <div class="col-md-4 col-sm-4">\n        [submit class:button-fluid "Request a service"]\n    </div>\n    <div class="col-md-8 col-sm-8">\n       <div class="stm-form-alert">\n          By submitting this form you will be scheduling a service appointment at no obligation and will be contacted within 48 hours by a service advisor.\n       </div>\n    </div>\n</div>\nService request\n[your-name]\nFrom: [your-name] <[your-email]>\nPhone: [your-tel]\n\nMake/model: [make-model]\nMileage: [mileage]\nBest time [time]\nReply-To: [your-email]\n\n\n\n\n[your-subject]\nMotors\nMessage Body:\n[your-message]\n\n--\n[your-email]\n\n\n\nYour message was sent successfully. Thanks.\nFailed to send your message. Please try later or contact the administrator by another method.\nValidation errors occurred. Please confirm the fields and submit it again.\nFailed to send your message. Please try later or contact the administrator by another method.\nPlease accept the terms to proceed.\nPlease fill in the required field.\nThis input is too long.\nThis input is too short.\nDate format seems invalid.\nThis date is too early.\nThis date is too late.\nFailed to upload file.\nThis file type is not allowed.\nThis file is too large.\nFailed to upload file. Error occurred.\nNumber format seems invalid.\nThis number is too small.\nThis number is too large.\nYour answer is not correct.\nEmail address seems invalid.\nURL seems invalid.\nTelephone number seems invalid.','Schedule service','','publish','closed','closed','','single-car-form_copy','','','2015-11-05 09:52:56','2015-11-05 09:52:56','',0,'http://bikes.loc/?post_type=wpcf7_contact_form&amp;p=587',0,'wpcf7_contact_form','',0);
