INSERT INTO `wp_posts` VALUES (1414,1,'2015-12-24 07:50:07','2015-12-24 07:50:07','[vc_row css=".vc_custom_1451023875067{margin-top: 58px !important;margin-bottom: 55px !important;}"][vc_column width="1/4" css=".vc_custom_1450948810755{margin-bottom: 30px !important;}"][vc_custom_heading text="SELL YOUR VEHICLE" font_container="tag:h2|text_align:left|line_height:35px" use_theme_fonts="yes" css=".vc_custom_1451024280177{margin-top: 7px !important;margin-bottom: 27px !important;}"][stm_color_separator align="text-left" title_holder="" css=".vc_custom_1450949033819{margin-bottom: 36px !important;}"][vc_column_text]<span style="color: #888888; font-size: 13px; line-height: 24px;">Interested in trading in your current vehicle? It would probably be good to have an estimate of what it\'s worth first. After all, trading in a vehicle is a lot less hassle than selling it yourself. And you can often lower your payments by trading in a vehicle as well. Win-win!</span>\n\n<span style="color: #888888; font-size: 13px; line-height: 24px;">We\'re here to help you make an informed decision. Fill out the simple form below, and we\'ll send you an estimated appraisal within 48 hours. From there, it\'s up to you what you want to do!</span>[/vc_column_text][/vc_column][vc_column width="3/4"][stm_sell_a_car][/vc_column][/vc_row]','Sell a Motorcycle','','publish','closed','closed','','sell-a-car','','','2015-12-24 07:50:07','2015-12-24 07:50:07','',0,'http://bikes.loc/?page_id=1414',0,'page','',0);
